const page = await browser.goto('https://news.ycombinator.com/');
const data = await browser.js(`
(() => {
  const rows = Array.from(document.querySelectorAll('tr.athing')).slice(0, 5);
  return rows.map(row => {
    const titleLink = row.querySelector('.titleline a');
    const title = titleLink ? titleLink.textContent.trim() : '';
    const url = titleLink ? titleLink.href : '';
    const id = row.id;
    const subtext = document.getElementById('score_' + id);
    const points = subtext ? parseInt(subtext.textContent) : null;
    return { id, title, url, points };
  });
})()
`);
return data;
